// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const BULK_UNITS = 100;
const BULK_FACTOR = 0.95;
const LARGE_ORDER_AMOUNT = 10000;
const PRODUCT_WIDTH = 20;
const UNITS_WIDTH = 5;
const MONEY_WIDTH = 14;

// Sections appear in this order. Each region lists its own tax rate and number format.
const REGIONS = {
  DE: {
    title: 'Germany',
    vatRate: 0.19,
    groupSeparator: '.',
    format: (sign, grouped, cents) => sign + grouped + ',' + cents + ' €',
  },
  FR: {
    title: 'France',
    vatRate: 0.2,
    groupSeparator: ' ',
    format: (sign, grouped, cents) => sign + grouped + ',' + cents + ' €',
  },
  UK: {
    title: 'United Kingdom',
    vatRate: 0.2,
    groupSeparator: ',',
    format: (sign, grouped, cents) => '£' + sign + grouped + '.' + cents,
  },
};

const roundToCents = (value) => Math.round(value * 100) / 100;

// Inserts the separator between groups of three, counting from the right.
function groupThousands(text, separator) {
  const groups = [];
  for (let end = text.length; end > 0; end -= 3) {
    groups.unshift(text.slice(Math.max(0, end - 3), end));
  }
  return groups.join(separator);
}

function regionConfig(region) {
  const config = REGIONS[region];
  if (!config) {
    throw new Error('unknown region: ' + region);
  }
  return config;
}

export function formatMoney(amount, region) {
  const { format, groupSeparator } = regionConfig(region);
  const sign = amount < 0 ? '-' : '';
  const [integerPart, cents] = Math.abs(amount).toFixed(2).split('.');
  return format(sign, groupThousands(integerPart, groupSeparator), cents);
}

// Money as printed in a sales row. The finance import has always received negative
// row amounts in a slightly different shape than formatMoney produces, and it is
// pinned by tests: in DE and UK the minus sign takes part in the grouping
// ("-.146,91 €", "£-,148.14"), in FR it does not.
function formatRowMoney(amount, region) {
  const { format, groupSeparator } = regionConfig(region);
  const [integerPart, cents] = amount.toFixed(2).split('.');
  if (region === 'FR') {
    const negative = integerPart.startsWith('-');
    const digits = negative ? integerPart.slice(1) : integerPart;
    return format(negative ? '-' : '', groupThousands(digits, groupSeparator), cents);
  }
  return format('', groupThousands(integerPart, groupSeparator), cents);
}

function grossAmount(sale, vatRate) {
  let net = sale.units * sale.unitPrice;
  if (sale.discountPct) {
    net -= (net * sale.discountPct) / 100;
  }
  if (sale.units >= BULK_UNITS) {
    net *= BULK_FACTOR;
  }
  net = roundToCents(net);
  const tax = roundToCents(net * vatRate);
  return roundToCents(net + tax);
}

